// Birdle: Squaredle-style word search on bird-themed boards.
// Boards come from boards.js, generated by tools/gen.py.

// Share of the board's points needed for each star: red numbers, white numbers, hints.
// The first star sits at the points the board's birds are worth, so finding all
// the birds first earns it; the others are at 60% and 80% (or evenly spaced
// above the first star if the birds are worth more than that).
function starThresholds() {
  const birds = regionBirds(board).reduce((t, b) => t + points(b.word), 0) / totalPoints;
  return [birds, Math.max(0.6, birds + (1 - birds) / 3), Math.max(0.8, birds + (2 * (1 - birds)) / 3)];
}
let STARS = [];
// The birds a board was built around. Its other birds are surprise birds: bird
// words (OWLET, KITE...) that turned up by chance. They score and show like
// birds, but the stars, the bird reveal and the bird count go by these.
const regionBirds = (b) => b.birds.filter((x) => !x.extra);
const MIN_LEN = 4;
const $ = (id) => document.getElementById(id);

const store = {
  get(key) { try { return JSON.parse(localStorage.getItem(key)); } catch { return null; } },
  set(key, value) { try { localStorage.setItem(key, JSON.stringify(value)); } catch {} },
};

let board, size, letters, required, bonusSet, birdWords, totalPoints, state;
let path = [];        // tile indices of the word being built
let typed = false;    // whether the current path came from the keyboard
let rotation = 0;

// Longer words score more, and the region's birds score double.
const BIRD_MULTIPLIER = 2;
const points = (w) => (w.length - 3) * (birdWords.has(w) ? BIRD_MULTIPLIER : 1);

// How many letters the letter hint reveals at the start and end of a word, by length.
function revealed(len) {
  if (len <= 5) return [1, 0];
  if (len === 6) return [2, 0];
  if (len === 7) return [2, 1];
  if (len <= 10) return [2, 2];
  if (len <= 14) return [3, 2];
  return [3, 3];
}
function hinted(w) {
  const [head, tail] = revealed(w.length);
  return w.slice(0, head) + '_'.repeat(w.length - head - tail) + (tail ? w.slice(-tail) : '');
}

// ----- screens ---------------------------------------------------------------

const boardLabel = (b) => `${b.level} · ${b.size}×${b.size}`;

// The home screen lists regions under their country or continent. Tapping a
// region opens its five boards; the open region is remembered.
function showRegions() {
  clearInterval(guideTimer);
  $('regions').hidden = false; $('game').hidden = true; $('back').hidden = true;
  const list = $('region-list');
  list.innerHTML = '';
  const open = store.get('birdle:open-region');
  let group, region, levels;
  for (const b of BOARDS) {
    if (b.group !== group) {
      group = b.group;
      const h = document.createElement('li');
      h.className = 'group-head';
      h.textContent = group;
      list.append(h);
    }
    if (b.region !== region) {
      region = b.region;
      const boards = BOARDS.filter((x) => x.region === region);
      const done = boards.filter(isComplete).length;
      const li = document.createElement('li');
      li.className = 'region';
      li.innerHTML = `<button class="region-head" aria-expanded="${open === region}">` +
        `<span class="flag">${b.flag}</span><span class="region-name">${b.name}</span>` +
        `<span class="done">${done ? `${done} of ${boards.length} ✓` : ''}</span><span class="chev">›</span></button><ul class="levels"></ul>`;
      levels = li.querySelector('.levels');
      levels.hidden = open !== region;
      const r = region;
      li.querySelector('.region-head').onclick = () => {
        store.set('birdle:open-region', store.get('birdle:open-region') === r ? null : r);
        showRegions();
      };
      list.append(li);
    }
    const saved = store.get('birdle:' + b.id);
    const s = saved && saved.grid === b.grid.join('') ? saved : null;
    const found = s ? s.found.length : 0;
    const all = regionBirds(b);
    const birds = s ? all.filter((x) => s.found.includes(x.word)).length : 0;
    const status = !s ? `${all.length} birds to find`
      : found === b.words.length ? 'Complete ✓'
      : `${birds} of ${all.length} birds · ${found} of ${b.words.length} words`;
    const li = document.createElement('li');
    li.innerHTML = `<button class="level"><span class="name">${boardLabel(b)}</span><span class="state">${status}</span></button>`;
    li.querySelector('button').onclick = () => openBoard(b);
    levels.append(li);
  }
  const openHead = list.querySelector('.region-head[aria-expanded="true"]');
  if (openHead) openHead.scrollIntoView({ block: 'nearest' });
}

function openBoard(b) {
  board = b;
  store.set('birdle:open-region', b.region);
  size = b.grid.length;
  letters = b.grid.join('');
  required = new Map(b.words.map((w) => [w.w, w]));
  bonusSet = new Set(b.bonus);
  birdWords = new Set(b.birds.map((x) => x.word));
  totalPoints = b.words.reduce((t, w) => t + points(w.w), 0);
  STARS = starThresholds();
  state = store.get('birdle:' + b.id);
  // A regenerated board gets a fresh start; old found words wouldn't be on it.
  if (!state || state.grid !== letters) state = freshState();
  // Boards saved before reveals existed start with the usual one.
  state.reveals ??= 1; state.revealed ||= []; state.birdReveal ??= false; state.guide ??= null;
  armed = null;
  path = []; rotation = 0;
  $('regions').hidden = true; $('game').hidden = false; $('back').hidden = false;
  $('region-name').textContent = `${b.flag} ${b.name} · ${b.level}`;
  $('progress').querySelector('.stars').innerHTML =
    STARS.map((s) => `<span class="star" style="left:${s * 100}%">★</span>`).join('');
  buildBoard();
  startGuide();
  render();
  window.scrollTo(0, 0);
}

const save = () => store.set('birdle:' + board.id, state);
const freshState = () => ({
  grid: letters, found: [], bonus: [], hintLetters: false, hintSort: false,
  reveals: 1, revealed: [], birdReveal: false, guide: null,
});
const isComplete = (b) => {
  const s = store.get('birdle:' + b.id);
  return !!s && s.grid === b.grid.join('') && s.found.length === b.words.length;
};

// ----- board -----------------------------------------------------------------

function buildBoard() {
  const el = $('board');
  el.style.gridTemplateColumns = `repeat(${size}, 1fr)`;
  el.style.transform = '';
  // Keep letters big on small boards and readable on 7x7 ones.
  const wrap = $('board-wrap');
  wrap.style.setProperty('--letter-size', `min(${(40 / size).toFixed(2)}vw, ${(12 / size).toFixed(2)}rem)`);
  wrap.style.setProperty('--num-size', `min(${(7 / size).toFixed(2)}vw + 0.5rem, ${(6.5 / size).toFixed(2)}rem)`);
  el.innerHTML = '';
  [...letters].forEach((ch, i) => {
    const t = document.createElement('div');
    t.className = 'tile' + (ch === '.' ? ' blank' : '');
    t.dataset.i = i;
    t.innerHTML = `<span class="letter">${ch === '.' ? '' : ch}</span><span class="n start"></span><span class="n use"></span>`;
    el.append(t);
  });
}

const tiles = () => [...$('board').children];
const adjacent = (a, b) => a !== b &&
  Math.abs(Math.floor(a / size) - Math.floor(b / size)) <= 1 && Math.abs((a % size) - (b % size)) <= 1;

// ----- swiping ---------------------------------------------------------------

// Only count a tile when the pointer is near its centre, so diagonal swipes
// don't clip the neighbouring tiles.
function tileAt(x, y) {
  const t = document.elementFromPoint(x, y)?.closest('.tile');
  if (!t || t.classList.contains('blank')) return null;
  const r = t.getBoundingClientRect();
  const dx = x - (r.left + r.width / 2), dy = y - (r.top + r.height / 2);
  return Math.hypot(dx, dy) <= r.width * 0.42 ? +t.dataset.i : null;
}

function extend(i) {
  if (i === null) return;
  if (path.length >= 2 && path[path.length - 2] === i) path.pop();          // backtrack
  else if (!path.length || (adjacent(path[path.length - 1], i) && !path.includes(i))) path.push(i);
  else return;
  renderPath();
}

let dragging = false;
$('board-wrap').addEventListener('pointerdown', (e) => {
  const i = tileAt(e.clientX, e.clientY);
  if (i === null) return;
  e.preventDefault();
  dragging = true; typed = false; path = [];
  $('board-wrap').setPointerCapture(e.pointerId);
  extend(i);
});
$('board-wrap').addEventListener('pointermove', (e) => { if (dragging) extend(tileAt(e.clientX, e.clientY)); });
$('board-wrap').addEventListener('pointerup', (e) => {
  if (!dragging) return;
  dragging = false;
  // Like Squaredle, letting go well above the board cancels the word.
  if (e.clientY < $('board-wrap').getBoundingClientRect().top - 40) return clearPath();
  submit();
});
$('board-wrap').addEventListener('pointercancel', () => { dragging = false; clearPath(); });

// ----- typing ----------------------------------------------------------------

let typedWord = '', typedAlt = 0;

// All ways to spell `word` on the board.
function pathsFor(word) {
  const out = [];
  const walk = (p) => {
    if (p.length === word.length) return out.push(p);
    const last = p[p.length - 1];
    for (let j = 0; j < letters.length; j++) {
      if (letters[j] === word[p.length] && !p.includes(j) && (last === undefined || adjacent(last, j))) walk([...p, j]);
    }
  };
  walk([]);
  return out;
}

function retype() {
  typed = true;
  const options = pathsFor(typedWord);
  path = options.length ? options[typedAlt % options.length] : [];
  renderPath();
}

document.addEventListener('keydown', (e) => {
  if ($('game').hidden || e.metaKey || e.ctrlKey || e.altKey || document.querySelector('dialog[open]')) return;
  if (e.key === 'Enter') submit();
  else if (e.key === 'Escape') clearPath();
  else if (e.key === 'Backspace') { typedWord = typedWord.slice(0, -1); typedAlt = 0; retype(); }
  else if (e.key === ' ') { typedAlt++; retype(); }      // cycle between same-letter squares
  else if (/^[a-z]$/i.test(e.key)) { typedWord += e.key.toUpperCase(); typedAlt = 0; retype(); }
  else return;
  e.preventDefault();
});

// ----- scoring ---------------------------------------------------------------

function wordOnBoard() {
  return typed ? typedWord : path.map((i) => letters[i]).join('');
}

function submit() {
  const w = wordOnBoard();
  if (typed && w.length && !path.length) { flash(w, 'Not on the board'); return clearPath(); }
  if (w.length === 0) return clearPath();
  if (path.length === 1 && !typed) return clearPath();   // a tap, not a word
  if (w.length < MIN_LEN) flash(w, 'Too short');
  else if (state.found.includes(w) || state.bonus.includes(w)) say(`${w}: already found`, 'neutral');
  else if (required.has(w)) {
    clearPath();
    return addFound(w, w === state.guide);
  } else if (bonusSet.has(w)) {
    state.bonus.push(w);
    save();
    toast(`${w}: bonus word`);
  } else flash(w, 'Not in word list');
  clearPath();
  render();
}

// Records a required word as found, whether the player found it or used a reveal on it.
function addFound(w, viaReveal) {
  const before = starsEarned();
  state.found.push(w);
  if (viaReveal) { state.revealed.push(w); state.guide = null; startGuide(); }
  // Finding every bird earns one more reveal, once per board.
  let extra = '';
  if (!state.birdReveal && regionBirds(board).every((b) => state.found.includes(b.word))) {
    state.birdReveal = true;
    state.reveals++;
    extra = '💡 +1 reveal';
  }
  save();
  const bird = board.birds.find((b) => b.word === w);
  const earned = starsEarned();
  const done = state.found.length === board.words.length;
  if (done) toast('🎉 Board complete! Every word found.');
  else {
    const star = earned > before
      ? ['★ Red numbers unlocked', '★ White numbers unlocked', '★ Hints unlocked'][earned - 1] : '';
    const found = (viaReveal ? '💡 ' : '') + (bird ? `${bird.extra ? '✨ Surprise bird: ' : '🐦 '}${bird.bird}! +${points(w)}` : `${w} +${points(w)}`);
    toast([found, star, extra].filter(Boolean).join(' · '));
  }
  render();
  // A newly found bird pops up its card; a finished board then offers the next one.
  if (bird) showBird(bird, done ? showComplete : null);
  else if (done) showComplete();
}

// ----- reveals ---------------------------------------------------------------

// Like Squaredle: reveals only work on 4 to 6 letter words. A reveal picks a
// random missing word of one length, or once the hints are unlocked, the
// missing word you tap (twice, so a stray tap doesn't waste it). The word's
// squares then light up in order on the board, and it counts once you swipe it.
const REVEALABLE = (w) => w.length <= 6;
let armed = null, armedTimer;
const noReveals = () => say(state.birdReveal ? 'No reveals left on this board' : 'No reveals left. Find all the birds to earn one.', 'neutral');
// Closes the word list so the glowing squares can be seen.
function toBoard(text) {
  $('words').close();
  $('board-wrap').scrollIntoView({ behavior: 'smooth', block: 'center' });
  say(text, 'neutral');
}
const tracingFirst = () => toBoard('💡 Swipe the glowing word on the board first');
function revealRandom(len) {
  if (state.guide) return tracingFirst();
  if (!state.reveals) return noReveals();
  const left = board.words.map((w) => w.w).filter((w) => w.length === len && !state.found.includes(w));
  // Leave the birds for the player while there are other words to show.
  const pool = left.filter((w) => !birdWords.has(w));
  const choices = pool.length ? pool : left;
  if (!choices.length) return;
  useReveal(choices[Math.floor(Math.random() * choices.length)]);
}
function useReveal(w) {
  state.reveals--;
  state.guide = w;
  armed = null;
  save();
  render();
  startGuide();
  toBoard('💡 Swipe the glowing squares in order');
}
// Lights up the revealed word's squares one by one, over and over, until it's swiped.
let guideTimer = null;
function startGuide() {
  clearInterval(guideTimer);
  guideTimer = null;
  tiles().forEach((t) => t.classList.remove('guide'));
  if (!state.guide) return;
  const steps = pathsFor(state.guide)[0];
  let k = 0;
  guideTimer = setInterval(() => {
    k = (k + 1) % (steps.length + 3);      // all lit, then a short pause before starting again
    tiles().forEach((t, i) => t.classList.toggle('guide', steps.slice(0, k).includes(i)));
  }, 450);
}
function tapMissing(w) {
  if (state.guide) return tracingFirst();
  if (!state.reveals) return noReveals();
  if (armed === w) { clearTimeout(armedTimer); return useReveal(w); }
  armed = w;
  clearTimeout(armedTimer);
  armedTimer = setTimeout(() => { armed = null; render(); }, 3000);
  say('Tap it again to use a reveal', 'neutral');
  render();
}

function starsEarned() {
  const got = state.found.reduce((t, w) => t + points(w), 0) / totalPoints;
  return STARS.filter((s) => got >= s).length;
}

// ----- rendering -------------------------------------------------------------

function clearPath() { path = []; typedWord = ''; typedAlt = 0; typed = false; renderPath(); }

function renderPath() {
  tiles().forEach((t, i) => t.classList.toggle('sel', path.includes(i)));
  const cur = $('current');
  const word = typed ? typedWord : path.map((i) => letters[i]).join('');
  const msg = !word && message;
  cur.className = msg ? `msg ${msg.kind}` : (typed && word && !path.length ? 'bad' : '');
  cur.textContent = msg ? msg.text : word;
  const wrap = $('board-wrap').getBoundingClientRect();
  const pts = path.map((i) => {
    const r = tiles()[i].getBoundingClientRect();
    return `${r.left + r.width / 2 - wrap.left},${r.top + r.height / 2 - wrap.top}`;
  });
  $('trail').innerHTML = pts.length > 1 ? `<polyline points="${pts.join(' ')}"/>` : '';
}

function render() {
  const stars = starsEarned();
  const got = state.found.reduce((t, w) => t + points(w), 0);
  $('progress').querySelector('.fill').style.width = `${(100 * got) / totalPoints}%`;
  $('progress').querySelectorAll('.star').forEach((s, i) => s.classList.toggle('on', i < stars));

  // Tile numbers count only words still to find; a tile fades when none are left.
  const left = board.words.filter((w) => !state.found.includes(w.w));
  // Bird tweets mark where each missing bird starts.
  const tweets = left.filter((w) => regionBirds(board).some((b) => b.word === w.w));
  tiles().forEach((t, i) => {
    if (letters[i] === '.') return;
    const starts = left.filter((w) => w.s.includes(i)).length;
    const uses = left.filter((w) => w.u.includes(i)).length;
    const fmt = (n) => (n >= 10 ? '+' : n || '');
    t.querySelector('.start').textContent = stars >= 1 ? fmt(starts) : '';
    t.querySelector('.use').textContent = stars >= 2 ? fmt(uses) : '';
    t.classList.toggle('done', uses === 0);
    t.classList.toggle('tweet', tweets.some((w) => w.s.includes(i)));
    t.style.transform = `rotate(${-rotation}deg)`;
  });

  const birdsFound = regionBirds(board).filter((b) => state.found.includes(b.word)).length;
  const surprises = board.birds.filter((b) => b.extra && state.found.includes(b.word)).length;
  $('count').querySelector('.words-count').innerHTML =
    `<b>${state.found.length}</b> / ${board.words.length} words` + (state.bonus.length ? ` <small>(+${state.bonus.length})</small>` : '');
  $('count').querySelector('.birds-count').textContent = `🐦 ${birdsFound} / ${regionBirds(board).length} birds` + (surprises ? ` · ✨ ${surprises}` : '');
  renderBirds();
  $('hints').hidden = stars < 3;
  $('hint-letters').checked = state.hintLetters;
  $('hint-sort').checked = state.hintSort;
  renderWords(stars >= 3);
}

function renderBirds() {
  const birds = regionBirds(board);
  const found = birds.filter((b) => state.found.includes(b.word)).length;
  const hintsOn = starsEarned() >= 3;
  const showLetters = hintsOn && state.hintLetters;
  const foundRow = (b) => `<button class="bird-row found" data-bird="${b.word}"><span class="name">${b.word} · ${b.bird}</span>` +
    `<span class="more">Photo and notes ›</span></button>`;
  // Found birds open their card; once hints are unlocked, a missing bird can take a reveal.
  // Surprise birds stay a surprise: they only appear once found.
  const surprises = board.birds.filter((b) => b.extra && state.found.includes(b.word));
  $('birds-panel').innerHTML = `<h3>🐦 Birds of ${board.name}: ${found} of ${birds.length}</h3>` +
    birds.map((b) => state.found.includes(b.word) ? foundRow(b)
      : `<div class="bird-row${armed === b.word ? ' armed' : ''}"${hintsOn && REVEALABLE(b.word) ? ` data-miss="${b.word}"` : ''}>` +
        `<span class="slots">${showLetters ? hinted(b.word) : '_'.repeat(b.word.length)}</span> <span class="note">${b.word.length} letters</span></div>`
    ).join('') +
    (surprises.length ? `<h3 class="surprise-head">✨ Surprise birds: ${surprises.length}</h3>` + surprises.map(foundRow).join('') : '');
}

function renderWords(hintsOn) {
  const showLetters = hintsOn && state.hintLetters;
  const sortAll = hintsOn && state.hintSort;
  const byLen = {};
  for (const w of board.words) (byLen[w.w.length] ||= []).push(w.w);
  let html = `<h3>Words: ${state.found.length} of ${board.words.length}</h3>` +
    `<p class="reveals">💡 Reveals remaining: ${state.reveals}` +
    `${state.birdReveal ? '' : ' <span class="note">(find all the birds for another)</span>'}</p>`;
  for (const len of Object.keys(byLen).sort((a, b) => a - b)) {
    const all = byLen[len];
    const found = all.filter((w) => state.found.includes(w));
    // Missing words appear as blanks; with the sort hint they sit in alphabetical order among the found ones.
    const items = sortAll ? all.slice().sort()
      : [...state.found.filter((w) => w.length == len), ...all.filter((w) => !found.includes(w)).sort()];
    html += `<div class="group-title">${len} letters · ${found.length} of ${all.length}</div><div class="words">` +
      items.map((w) => {
        const cls = (birdWords.has(w) ? ' bird' : '') + (state.revealed.includes(w) ? ' revealed' : '');
        if (found.includes(w)) return `<span class="word${cls}"${birdWords.has(w) ? ` data-bird="${w}"` : ''}>${w}</span>`;
        if (!sortAll && !showLetters) return '';
        const shown = showLetters ? hinted(w) : '_'.repeat(w.length);
        return `<span class="word missing${armed === w ? ' armed' : ''}"${REVEALABLE(w) ? ` data-miss="${w}"` : ''}>${shown}</span>`;
      }).join('') + '</div>';
    // Until the missing words show as blanks, say how many are left, with a reveal link for short words.
    const left = all.length - found.length;
    if (left && !sortAll && !showLetters) {
      html += `<p class="left">+${left} word${left > 1 ? 's' : ''} left` +
        (len <= 6 && state.reveals ? ` · <button class="link" data-reveal="${len}">Reveal a random word</button>` : '') + '</p>';
    }
  }
  $('word-list').innerHTML = html;
  $('bonus-list').innerHTML = state.bonus.length
    ? `<h3>Bonus words: ${state.bonus.length}</h3><div class="words">${state.bonus.map((w) => `<span class="word">${w}</span>`).join('')}</div>`
    : '';
}

// ----- messages --------------------------------------------------------------

// Messages show on the line above the board, where the word being built goes.
let message = null, messageTimer;
// kind: 'good' (green), 'bad' (red, for words that don't count) or 'neutral'.
function say(text, kind) {
  message = { text, kind };
  // The word list covers the board, so it shows its own copy of the message.
  const wm = $('words-msg');
  wm.textContent = $('words').open ? text : '';
  wm.className = `msg ${kind}`;
  clearTimeout(messageTimer);
  messageTimer = setTimeout(() => { message = null; wm.textContent = ''; renderPath(); }, 2200);
  renderPath();
}
const toast = (text) => say(text, 'good');
const flash = (word, why) => say(`${word}: ${why.toLowerCase()}`, 'bad');

// ----- controls --------------------------------------------------------------

$('rotate').onclick = () => {
  rotation = (rotation + 90) % 360;
  $('board').style.transform = `rotate(${rotation}deg)`;
  render();
};
// Taps in the bird panel and word list: a found bird opens its card, a missing word can be revealed.
for (const id of ['birds-panel', 'word-list']) {
  $(id).addEventListener('click', (e) => {
    const el = e.target.closest('[data-bird], [data-miss], [data-reveal]');
    if (!el) return;
    if (el.dataset.reveal) revealRandom(+el.dataset.reveal);
    else if (el.dataset.bird) showBird(board.birds.find((b) => b.word === el.dataset.bird));
    else tapMissing(el.dataset.miss);
  });
}
$('hint-letters').onchange = (e) => { state.hintLetters = e.target.checked; save(); render(); };
$('hint-sort').onchange = (e) => { state.hintSort = e.target.checked; save(); render(); };
// Two taps to start over, so a stray tap can't wipe a board.
let resetArmed;
$('reset').onclick = () => {
  if (!resetArmed) {
    $('reset').textContent = 'Tap again to clear all found words';
    resetArmed = setTimeout(() => { resetArmed = null; $('reset').textContent = 'Start this board over'; }, 3000);
    return;
  }
  clearTimeout(resetArmed); resetArmed = null;
  $('reset').textContent = 'Start this board over';
  state = freshState();
  save(); render(); startGuide();
};
$('back').onclick = showRegions;
const wordsDialog = $('words');
// The list reopens where you left it on each board.
const listScroll = {};
const listBody = wordsDialog.querySelector('.sheet-body');
$('count').onclick = () => { wordsDialog.showModal(); listBody.scrollTop = listScroll[board.id] || 0; };
// Saved as you scroll: by the time the dialog's close event fires, it has already lost its scroll position.
listBody.addEventListener('scroll', () => { if (wordsDialog.open) listScroll[board.id] = listBody.scrollTop; });
wordsDialog.querySelector('.close').onclick = () => wordsDialog.close();
// Tapping outside the list closes it too.
wordsDialog.addEventListener('click', (e) => { if (e.target === wordsDialog) wordsDialog.close(); });
// ----- bird cards ------------------------------------------------------------

// Photos come from iNaturalist, looked up by scientific name the first time a
// bird's card opens and remembered after that. Only Creative Commons photos
// are used, with their credit shown.
const INAT = 'https://api.inaturalist.org/v1';
async function birdPhoto(bird) {
  const key = 'birdle:photo:' + bird.sci;
  const cached = store.get(key);
  if (cached) return cached;
  const get = async (url) => { const r = await fetch(url); if (!r.ok) throw new Error(r.status); return r.json(); };
  const { results } = await get(`${INAT}/taxa?q=${encodeURIComponent(bird.sci)}&per_page=10`);
  const birds = results.filter((t) => t.iconic_taxon_name === 'Aves');
  const taxon = birds.find((t) => t.name === bird.sci) || birds.find((t) => t.matched_term === bird.sci) || birds[0];
  if (!taxon) throw new Error('no taxon');
  let photo = taxon.default_photo?.license_code ? taxon.default_photo : null;
  if (!photo) {
    const full = (await get(`${INAT}/taxa/${taxon.id}`)).results[0];
    photo = full.taxon_photos.map((p) => p.photo).find((p) => p.license_code);
  }
  if (!photo) throw new Error('no open photo');
  const info = {
    url: photo.medium_url || photo.url.replace('square', 'medium'),
    credit: photo.attribution,
    license: photo.license_code,
    page: `https://www.inaturalist.org/taxa/${taxon.id}`,
  };
  store.set(key, info);
  return info;
}
const licenseUrl = (code) => code === 'cc0'
  ? 'https://creativecommons.org/publicdomain/zero/1.0/'
  : `https://creativecommons.org/licenses/${code.replace(/^cc-/, '')}/4.0/`;

const card = $('bird-card');
let afterCard = null;
function showBird(bird, then = null) {
  afterCard = then;
  card.querySelector('.bird-name').textContent = bird.bird;
  card.querySelector('.sci').textContent = bird.sci || '';
  card.querySelector('.blurb').textContent = bird.blurb || '';
  card.querySelector('.note').textContent = bird.note;
  const fig = card.querySelector('figure');
  const img = fig.querySelector('img'), cap = fig.querySelector('figcaption');
  fig.className = 'loading';
  img.removeAttribute('src'); img.alt = bird.bird; cap.textContent = 'Loading photo…';
  card.showModal();
  card.scrollTop = 0;
  card.querySelector('.ok').focus();
  if (!bird.sci) return void (fig.className = 'failed');
  birdPhoto(bird).then((p) => {
    if (card.querySelector('.bird-name').textContent !== bird.bird) return;   // another card opened since
    img.onload = () => { fig.className = ''; };
    img.onerror = () => { fig.className = 'failed'; cap.textContent = 'Photo unavailable right now'; };
    img.src = p.url;
    // iNaturalist's credit line names the photographer and the licence.
    const link = (href, text) => Object.assign(document.createElement('a'), { href, textContent: text, target: '_blank', rel: 'noopener' });
    cap.replaceChildren(link(licenseUrl(p.license), p.credit), ' · ', link(p.page, 'iNaturalist'));
  }).catch(() => { fig.className = 'failed'; cap.textContent = 'Photo unavailable right now'; });
}
card.addEventListener('close', () => { const then = afterCard; afterCard = null; if (then) then(); });
card.querySelector('.ok').onclick = () => card.close();
card.querySelector('.close').onclick = () => card.close();

// ----- board complete --------------------------------------------------------

// The next board in this region that isn't finished yet, going up the levels and wrapping round.
function nextBoard() {
  const region = BOARDS.filter((b) => b.region === board.region);
  const at = region.indexOf(board);
  for (let k = 1; k < region.length; k++) {
    const b = region[(at + k) % region.length];
    if (!isComplete(b)) return b;
  }
  return null;
}
const complete = $('complete');
function showComplete() {
  const next = nextBoard();
  const birds = regionBirds(board).length;
  complete.querySelector('.summary').textContent = next
    ? `You found all ${board.words.length} words and ${birds} birds. Ready for the next one?`
    : `You found all ${board.words.length} words and ${birds} birds, and every ${board.name} board is done!`;
  const go = complete.querySelector('.go');
  go.hidden = !next;
  if (next) {
    go.textContent = `Play ${boardLabel(next)} ›`;
    go.onclick = () => { complete.close(); openBoard(next); };
  }
  complete.showModal();
  (next ? go : complete.querySelector('.home')).focus();
}
complete.querySelector('.home').onclick = () => { complete.close(); showRegions(); };
complete.querySelector('.stay').onclick = () => complete.close();

// How to play: a few short screens with Back / Next / Let's play.
const rules = $('rules');
const steps = [...rules.querySelectorAll('.step')];
let step = 0;
function showStep(n) {
  step = n;
  steps.forEach((el, i) => { el.hidden = i !== n; });
  rules.querySelector('.back').disabled = n === 0;
  rules.querySelector('.next').textContent = n === steps.length - 1 ? "Let's play" : 'Next';
  rules.querySelector('.dots').innerHTML = steps.map((_, i) => `<i class="${i === n ? 'on' : ''}"></i>`).join('');
}
function openRules() {
  showStep(0);
  rules.showModal();
  rules.scrollTop = 0;
  rules.querySelector('.next').focus();
}
rules.querySelector('.back').onclick = () => showStep(step - 1);
rules.querySelector('.next').onclick = () => (step < steps.length - 1 ? showStep(step + 1) : rules.close());
rules.querySelector('.close').onclick = () => rules.close();
$('help').onclick = openRules;
window.addEventListener('resize', renderPath);

showRegions();
if (!store.get('birdle:seen-rules')) { store.set('birdle:seen-rules', true); openRules(); }
